from collections import deque

def compute_distance_to_4s(grid):
    """Compute distance from 4-locations"""
    rows = len(grid)
    cols = len(grid[0])
    dist = [[float('inf')] * cols for _ in range(rows)]

    # Initialize: 4s have distance 0
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                dist[r][c] = 0
                queue.append((r, c))

    # BFS
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != 4 and dist[nr][nc] == float('inf'):
                    dist[nr][nc] = dist[r][c] + 1
                    queue.append((nr, nc))

    return dist

