def simple_solution():
    """
    Simple hypothesis: Change 0s that are 4-adjacent to any 9 into 2s.
    Keep 2s as 2s. Keep 9s as 9s.
    """
    rows = len(input_grid)
    cols = len(input_grid[0])

    # Create result grid as copy
    result = [row[:] for row in input_grid]

    # First pass: mark positions that should change
    positions_to_change = set()

    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 0:
                # Check if 4-adjacent to any 9
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
